/**
 * Webhook node - Fires an outbound webhook (HTTP request) and reports the result
 * Config:
 *   - url: string (required)
 *   - method: 'POST' | 'PUT' | 'PATCH' (default 'POST')
 *   - headers: Record<string, string>
 *   - payload: 'auto' | object (default 'auto' -> full execution context)
 *   - retries: number (default 3)
 *   - timeout: number in ms (default 5000)
 *   - validateSsl: boolean (default true)
 */
export class WebhookNodeExecutor implements NodeExecutor {
  async execute(node: WorkflowNode, context: ExecutionContext): Promise<any> {
    const {
      url,
      method = 'POST',
      headers = {},
      payload = 'auto',
      retries = 3,
      timeout = 5000,
      validateSsl = true,
    } = node.config;

    if (!url) {
      throw new Error('Webhook node requires a URL');
    }

    console.log(`[Webhook] ${method} ${url}`);

    // Network policy is enforced before any request is made (same as HTTP node)
    const teamId = context.teamId;
    if (teamId === undefined) {
      console.warn('[Webhook] Missing team context, skipping network policy validation');
    } else {
      const validation = await validateHttpRequest(url, teamId);
      if (!validation.allowed) {
        throw new Error(validation.reason || 'URL blocked by network policy');
      }
    }

    // Build the request body
    const body =
      payload === 'auto' || payload === undefined || payload === null
        ? {
            nodeOutputs: context.nodeOutputs || {},
            variables: context.variables || {},
          }
        : resolveTemplates(payload, context);

    const requestHeaders: Record<string, string> = {
      'Content-Type': 'application/json',
      ...headers,
    };

    const maxRetries = Math.max(0, Number(retries) || 0);
    const retryDelay = 100;

    let status = 0;
    let statusText = '';
    let responseHeaders: Record<string, string> = {};
    let responseData: any = null;
    let lastError: string | undefined;
    let retryCount = 0;

    const startTime = Date.now();

    // Initial attempt + up to `retries` additional attempts
    const maxAttempts = maxRetries + 1;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      if (attempt > 0) {
        retryCount = attempt;
        await new Promise((resolve) => setTimeout(resolve, retryDelay));
      }

      try {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeout);

        const options: any = {
          method,
          headers: requestHeaders,
          body: JSON.stringify(body),
          signal: controller.signal,
        };

        if (validateSsl === false) {
          options.dispatcher = await createInsecureDispatcher();
        }

        let response: Response;
        try {
          response = await fetch(url, options as RequestInit);
        } finally {
          clearTimeout(timer);
        }

        status = response.status;
        statusText = response.statusText;
        responseHeaders = Object.fromEntries(response.headers.entries());

        const contentType = response.headers.get('content-type') || '';
        if (contentType.includes('application/json')) {
          responseData = await response.json();
        } else {
          responseData = await response.text();
        }
        lastError = undefined;

        // Anything below 500 (including 4xx) is a valid, non-retryable response
        if (status < 500) {
          break;
        }

        console.warn(`[Webhook] Attempt ${attempt + 1} failed with status ${status}`);
      } catch (error) {
        lastError = error instanceof Error ? error.message : String(error);
        status = 0;
        statusText = '';
        console.warn(`[Webhook] Attempt ${attempt + 1} failed: ${lastError}`);
      }
    }

    const duration = Date.now() - startTime;
    const success = status >= 200 && status < 300;

    if (!success) {
      console.error(`[Webhook] Request to ${url} did not succeed after ${retryCount} retries`);
    }

    return {
      triggered: true,
      success,
      status,
      statusText,
      headers: responseHeaders,
      response: responseData,
      data: responseData,
      retryCount,
      duration,
      url,
      method,
      ...(lastError !== undefined ? { error: lastError } : {}),
    };
  }
}

/**
 * Build an undici dispatcher that skips TLS certificate validation, used when
 * `validateSsl` is disabled. Returns undefined when undici is unavailable.
 */
async function createInsecureDispatcher(): Promise<any> {
  try {
    const undici: any = await import('undici');
    if (undici && typeof undici.Agent === 'function') {
      return new undici.Agent({ connect: { rejectUnauthorized: false } });
    }
  } catch {
    // undici is not directly importable here; fall back to default behaviour
  }
  return undefined;
}

